package com.arenashowdown.lobby;

import net.kyori.adventure.text.Component;import net.kyori.adventure.text.format.NamedTextColor;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import java.util.*;

final class LobbyMenu implements Listener {
    static final Component TITLE=Component.text("Arena Showdown - Minigames",NamedTextColor.DARK_RED);private final ArenaLobbyPlugin plugin;private final List<String> ids=List.of("corrida","skywars","battle-royale","desafio-de-sorte","parkour","roube-a-bandeira","csgo","tnt-run");
    LobbyMenu(ArenaLobbyPlugin p){plugin=p;}
    void open(Player p){Inventory inv=Bukkit.createInventory(null,27,TITLE);for(int i=0;i<ids.size();i++){String id=ids.get(i),root="minigames."+id;boolean enabled=plugin.getConfig().getBoolean(root+".enabled");Material material=Material.matchMaterial(plugin.getConfig().getString(root+".icon","BARRIER"));ItemStack item=new ItemStack(material==null?Material.BARRIER:material);ItemMeta m=item.getItemMeta();m.displayName(Component.text(plugin.getConfig().getString(root+".name",id),enabled?NamedTextColor.GREEN:NamedTextColor.RED));m.lore(List.of(Component.text(enabled?"Disponivel":"Indisponivel",enabled?NamedTextColor.GREEN:NamedTextColor.RED),Component.text("Arena: "+plugin.getConfig().getString(root+".arena","nao configurada"),NamedTextColor.GRAY),Component.text("Pontuacao maxima: "+plugin.getConfig().getInt(root+".max-points",0),NamedTextColor.GOLD)));item.setItemMeta(m);inv.setItem(9+i,item);}inv.setItem(22,item(Material.NETHER_STAR,"Campeonato: "+plugin.state().view.name()));if(p.hasPermission("arena.lobby.admin"))inv.setItem(26,item(Material.LIME_DYE,"Iniciar proxima rodada"));p.openInventory(inv);}
    private ItemStack item(Material type,String name){ItemStack i=new ItemStack(type);ItemMeta m=i.getItemMeta();m.displayName(Component.text(name,NamedTextColor.GOLD));i.setItemMeta(m);return i;}
    @EventHandler void click(InventoryClickEvent e){if(!e.getView().title().equals(TITLE))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;if(e.getRawSlot()==26&&p.hasPermission("arena.lobby.admin")){p.closeInventory();Bukkit.dispatchCommand(Bukkit.getConsoleSender(),"arena next "+plugin.championship());return;}if(e.getRawSlot()>=9&&e.getRawSlot()<17)p.sendMessage(Component.text("Use o painel administrativo para iniciar partidas; jogadores podem apenas consultar.",NamedTextColor.YELLOW));}
}
